import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_min_dim1(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math_constants.h>
#include <c10/cuda/CUDAStream.h>
#include <cstdint>
#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float cute_min_update(float best, float value)
{
    if (isnan(value) ||
        value < best ||
        (value == best && signbit(value) && !signbit(best))) {
        return value;
    }
    return best;
}
__global__ void cute_min_dim1_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int B,
    int R,
    int C)
{
    const int64_t nvec = (static_cast<int64_t>(C) + 3) / 4;
    const int64_t tile_stride = static_cast<int64_t>(gridDim.x);
    const int b = static_cast<int>(blockIdx.y);
    if (b >= B) {
        return;
    }
    const int warp_id = static_cast<int>(threadIdx.x) >> 5;
    const int lane = static_cast<int>(threadIdx.x) & 31;
    for (int64_t tile = static_cast<int64_t>(blockIdx.x);
         tile < nvec;
         tile += tile_stride) {
        const int64_t vec = tile * 4 + warp_id;
        if (vec >= nvec) {
            continue;
        }
        const int c0 = static_cast<int>(vec * 4);
        float best0 = CUDART_INF_F;
        float best1 = CUDART_INF_F;
        float best2 = CUDART_INF_F;
        float best3 = CUDART_INF_F;
        const bool full_vec = c0 + 3 < C;
        for (int r = lane; r < R; r += 32) {
            const float* row =
                x + (static_cast<size_t>(b) * R + r) * C;
            const float* ptr = row + c0;
            if (full_vec &&
                (reinterpret_cast<uintptr_t>(ptr) & 15u) == 0u) {
                const float4 value =
                    *reinterpret_cast<const float4*>(ptr);
                best0 = cute_min_update(best0, value.x);
                best1 = cute_min_update(best1, value.y);
                best2 = cute_min_update(best2, value.z);
                best3 = cute_min_update(best3, value.w);
            } else {
                if (c0 < C) {
                    best0 = cute_min_update(best0, ptr[0]);
                }
                if (c0 + 1 < C) {
                    best1 = cute_min_update(best1, ptr[1]);
                }
                if (c0 + 2 < C) {
                    best2 = cute_min_update(best2, ptr[2]);
                }
                if (c0 + 3 < C) {
                    best3 = cute_min_update(best3, ptr[3]);
                }
            }
        }
        constexpr unsigned mask = 0xffffffffu;
        for (int offset = 16; offset > 0; offset >>= 1) {
            best0 = cute_min_update(
                best0, __shfl_down_sync(mask, best0, offset));
            best1 = cute_min_update(
                best1, __shfl_down_sync(mask, best1, offset));
            best2 = cute_min_update(
                best2, __shfl_down_sync(mask, best2, offset));
            best3 = cute_min_update(
                best3, __shfl_down_sync(mask, best3, offset));
        }
        if (lane == 0) {
            float* dst = out + static_cast<size_t>(b) * C + c0;
            if (full_vec &&
                (reinterpret_cast<uintptr_t>(dst) & 15u) == 0u) {
                *reinterpret_cast<float4*>(dst) = make_float4(
                    best0, best1, best2, best3);
            } else {
                if (c0 < C) {
                    dst[0] = best0;
                }
                if (c0 + 1 < C) {
                    dst[1] = best1;
                }
                if (c0 + 2 < C) {
                    dst[2] = best2;
                }
                if (c0 + 3 < C) {
                    dst[3] = best3;
                }
            }
        }
    }
}

torch::Tensor cute_min_dim1(torch::Tensor x)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "x must be a 3D tensor");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat,
        "cute_min_dim1 currently supports float32 tensors only");

    auto x_contiguous = x.contiguous();

    const int B = static_cast<int>(x_contiguous.size(0));
    const int R = static_cast<int>(x_contiguous.size(1));
    const int C = static_cast<int>(x_contiguous.size(2));

    auto out = torch::empty(
        {static_cast<int64_t>(B), static_cast<int64_t>(C)},
        x_contiguous.options());

    constexpr int threads = 256;
    if (B == 0 || C == 0) {
        return out;
    }
    const int64_t nvec =
        (static_cast<int64_t>(C) + 3) / 4;
    const int64_t needed_blocks_x =
        (nvec + 3) / 4;
    const int blocks_x = static_cast<int>(
        needed_blocks_x < 1024 ? needed_blocks_x : 1024);
    const int blocks_y = B < 65535 ? B : 65535;
    dim3 block(threads);
    dim3 grid(blocks_x, blocks_y);
    cudaStream_t stream =
        c10::cuda::getCurrentCUDAStream().stream();
    cute_min_dim1_kernel<<<grid, block, 0, stream>>>(
        x_contiguous.data_ptr<float>(),
        out.data_ptr<float>(),
        B,
        R,
        C);
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(
        err == cudaSuccess,
        "CUTE min reduction kernel launch failed: ",
        cudaGetErrorString(err));
    return out;
}
"""

cute_ext = load_inline(
    name="cute_min_dim1_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_min_dim1"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.dim not in (1, -2):
            raise ValueError("ModelNew supports reduction over dimension 1 only")
        return self._ext.cute_min_dim1(x)

